contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _owner) public payable {
        require(_owner != address(0));

        address before = c.owner(); if (__ESBMC_reverted()) return;

        bool success;
        c.setOwner(_owner); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            success = false;
        } else {
            success = true;
        }

        address currentOwner = c.owner(); if (__ESBMC_reverted()) return;

        assert(success && currentOwner == _owner);
    }

    receive() external payable {}
}

